body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  color: #111827;
  background: transparent;
}

.timeline-card {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  overflow: hidden;
}

.head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5e7eb;
}

.head span {
  display: block;
  color: #0f766e;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

h2 {
  margin: 4px 0;
  font-size: 22px;
}

p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.count {
  min-width: 44px;
  height: 38px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: #111827;
  color: white;
  font-weight: 900;
}

.timeline {
  height: calc(100% - 102px);
  overflow: auto;
  padding: 14px 2px 8px;
}

.item {
  position: relative;
  display: grid;
  grid-template-columns: 88px 14px 1fr;
  gap: 12px;
  padding: 0 0 16px;
  cursor: pointer;
}

.item::after {
  content: "";
  position: absolute;
  left: 95px;
  top: 16px;
  bottom: 0;
  width: 1px;
  background: #e5e7eb;
}

.item:last-child::after {
  display: none;
}

.time {
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  text-align: right;
  padding-top: 3px;
}

.dot {
  width: 12px;
  height: 12px;
  margin-top: 4px;
  border-radius: 50%;
  background: #2563eb;
  box-shadow: 0 0 0 4px #eff6ff;
  z-index: 1;
}

.item.POS .dot {
  background: #14b8a6;
  box-shadow: 0 0 0 4px #ccfbf1;
}

.item.Sales .dot {
  background: #2563eb;
  box-shadow: 0 0 0 4px #dbeafe;
}

.item.Inventory .dot,
.item.Warehouse .dot {
  background: #d97706;
  box-shadow: 0 0 0 4px #fef3c7;
}

.item.Cash .dot {
  background: #16a34a;
  box-shadow: 0 0 0 4px #dcfce7;
}

.content {
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 10px 12px;
  background: #fff;
}

.item:hover .content {
  border-color: #14b8a6;
  background: #f0fdfa;
}

.topline {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.title {
  font-weight: 900;
}

.group {
  padding: 3px 7px;
  border-radius: 999px;
  background: #f1f5f9;
  color: #475569;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.ref {
  margin-top: 3px;
  font-size: 12px;
  color: #334155;
  font-weight: 800;
}

.detail {
  margin-top: 4px;
  color: #64748b;
  font-size: 12px;
}

.empty {
  padding: 26px;
  border: 1px dashed #cbd5e1;
  border-radius: 8px;
  text-align: center;
  color: #64748b;
}

.foot {
  padding-top: 8px;
  border-top: 1px solid #e5e7eb;
  color: #64748b;
  font-size: 11px;
}

