function formatTime(value) {
  if (!value) return "--:--";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value).slice(11, 16) || "--:--";
  return date.toLocaleTimeString("hr-HR", {
    hour: "2-digit",
    minute: "2-digit"
  });
}
function esc(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}
function openEvent(index) {
  const events = appsmith.model?.events || [];
  const selected = events[index] || {};
  appsmith.updateModel({
    selectedEvent: selected
  });
  appsmith.triggerEvent("onTimelineOpen");
}
function render(model = {}) {
  const events = model.events || [];
  const root = document.getElementById("timeline");
  document.getElementById("eventCount").innerText = events.length;
  document.getElementById("generatedAt").innerText = "Updated: " + (model.generatedAt || "");
  if (!root) return;
  if (!events.length) {
    root.innerHTML = `<div class="empty">No activity recorded today.</div>`;
    return;
  }
  root.innerHTML = events.map((event, index) => `
    <div class="item ${esc(event.eventGroup)}" onclick="openEvent(${index})">
      <div class="time">${formatTime(event.eventTime)}</div>
      <div class="dot"></div>
      <div class="content">
        <div class="topline">
          <div class="title">${esc(event.eventTitle)}</div>
          <div class="group">${esc(event.eventGroup)}</div>
        </div>
        <div class="ref">${esc(event.referenceNumber)}</div>
        <div class="detail">${esc(event.eventDetail)}</div>
      </div>
    </div>
  `).join("");
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

